    async fn response_json(response: Response) -> Result<(StatusCode, serde_json::Value)> {
        let status = response.status();
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .context("read response body")?;
        let body = serde_json::from_slice(&bytes).context("decode response body")?;
        Ok((status, body))
    }

    #[test]
    fn signed_public_bootstrap_is_secret_free_and_commit_bound() -> Result<()> {
        let authority = x0x::identity::AgentKeypair::generate()?;
        let recipient = x0x::identity::AgentKeypair::generate()?;
        let authority_hex = hex::encode(authority.agent_id().as_bytes());
        let recipient_hex = hex::encode(recipient.agent_id().as_bytes());
        let mut group = x0x::groups::GroupInfo::with_policy(
            "Acceptance".to_string(),
            String::new(),
            authority.agent_id(),
            "ab".repeat(32),
            x0x::groups::GroupPolicyPreset::PublicOpen.to_policy(),
        );
        group.roster_revision = 1;
        group.add_member(
            recipient_hex.clone(),
            x0x::groups::GroupRole::Member,
            Some(authority_hex.clone()),
            Some("Studio".to_string()),
        );
        group.seal_commit(&authority, now_millis_u64())?;

        let snapshot = signed_public_bootstrap_snapshot(group).context("public snapshot")?;
        assert!(snapshot.shared_secret.is_none());
        assert!(snapshot.issued_invites.is_empty());
        assert!(snapshot.issued_invite_secrets.is_empty());
        assert_eq!(snapshot.commit_log.len(), 1);
        assert!(validate_public_group_bootstrap(
            &snapshot,
            &authority_hex,
            &recipient_hex
        ));

        let mut tampered = snapshot;
        tampered
            .members_v2
            .get_mut(&recipient_hex)
            .context("recipient member")?
            .role = x0x::groups::GroupRole::Admin;
        assert!(!validate_public_group_bootstrap(
            &tampered,
            &authority_hex,
            &recipient_hex
        ));
        Ok(())
    }

    /// Why: #297 — a non-TreeKEM joiner that missed the authority's
    /// `MemberAdded` commit during the join window had no repair path and
    /// stayed absent from its own roster permanently (silent 403 on every
    /// send). The roster-repair poll must keep pulling the staged join result
    /// from the inviter while the local roster lacks the joiner, and must
    /// stop — dropping the expected-inviter pin — as soon as the roster lists
    /// the joiner as active, with no TreeKEM group ever being installed.
    #[tokio::test]
    async fn non_treekem_join_result_poll_repairs_roster_then_stops() -> Result<()> {
        let (state, _dir) = secure_endpoint_test_state().await?;
        let (info, owner_hex) = sole_owner_group();
        let group_id = info.mls_group_id.clone();
        let event_group_id = info.stable_group_id().to_string();
        let joiner_hex = "bb".repeat(32);
        let inviter = x0x::identity::AgentKeypair::generate()?.agent_id();
        let expected_key = join_result_key(&event_group_id, &joiner_hex);
        record_expected_join_result_inviter(
            state.as_ref(),
            expected_key.clone(),
            hex::encode(inviter.as_bytes()),
        );
        state
            .named_groups
            .write()
            .await
            .insert(group_id.clone(), info);

        let poll_state = Arc::clone(&state);
        let poll_group_id = group_id.clone();
        let poll_member = joiner_hex.clone();
        let poll = tokio::spawn(async move {
            poll_join_result_until_membership_confirmed(
                poll_state,
                poll_group_id,
                event_group_id,
                inviter,
                poll_member,
                false,
                // No `MemberJoined` payload: this test pins the loop's exit
                // conditions, which the #333 resend arm must leave unchanged.
                None,
            )
            .await;
        });

        // The roster does not list the joiner yet, so the repair poll must
        // still be running (it re-requests the staged commit every interval).
        tokio::time::sleep(Duration::from_millis(200)).await;
        assert!(
            !poll.is_finished(),
            "non-TreeKEM repair poll exited before roster membership was confirmed"
        );

        // The missed commit finally lands (gossip redelivery or a fetch
        // response): the roster now lists the joiner as an active member.
        {
            let mut groups = state.named_groups.write().await;
            let info = groups
                .get_mut(&group_id)
                .context("group must exist in test state")?;
            info.add_member(
                joiner_hex.clone(),
                x0x::groups::GroupRole::Member,
                Some(owner_hex),
                None,
            );
        }

        // A poll iteration can be parked inside a failing send attempt for
        // multiple per-attempt timeouts; the confirmation check runs at the
        // top of the next iteration, so allow ample slack.
        tokio::time::timeout(Duration::from_secs(90), poll)
            .await
            .context("repair poll must stop once the roster lists the joiner")??;
        assert!(
            expected_join_result_inviter(state.as_ref(), &expected_key).is_none(),
            "expected-inviter pin must be dropped when the repair poll stops"
        );
        Ok(())
    }

    #[tokio::test]
    async fn agent_card_group_invite_from_get_card_is_accepted_on_join() -> Result<()> {
        let (authority, _authority_dir) = secure_endpoint_test_state().await?;
        let (joiner, _joiner_dir) = secure_endpoint_test_state().await?;
        let group_id = "5c".repeat(32);
        let authority_id = authority.agent.agent_id();
        let mut authority_info = x0x::groups::GroupInfo::with_policy(
            "card invite provenance".to_string(),
            "base-state fields should survive card export".to_string(),
            authority_id,
            group_id.clone(),
            x0x::groups::GroupPolicyPreset::PublicOpen.to_policy(),
        );
        authority_info.recompute_state_hash();
        let stable_group_id = authority_info.stable_group_id().to_string();
        let authority_state_hash = authority_info.state_hash.clone();
        let authority_members = authority_info.members_v2.clone();
        authority
            .named_groups
            .write()
            .await
            .insert(group_id.clone(), authority_info);

        let card_response = get_agent_card(
            State(Arc::clone(&authority)),
            Some(axum::extract::Extension(
                crate::server::rider_auth::ActorContext::Owner { durable: true },
            )),
            Query(CardQuery {
                display_name: Some("authority".to_string()),
                include_groups: Some(true),
                include_local_addresses: false,
            }),
        )
        .await
        .into_response();
        let (card_status, card_body) = response_json(card_response).await?;
        assert_eq!(card_status, StatusCode::OK);
        let card: x0x::groups::card::AgentCard = serde_json::from_value(card_body["card"].clone())
            .context("decode agent card from handler response")?;
        let card_group = card
            .groups
            .iter()
            .find(|group| group.name == "card invite provenance")
            .expect("agent card should include the named group invite");
        let invite = x0x::groups::invite::SignedInvite::from_link(&card_group.invite_link)
            .map_err(|e| anyhow::anyhow!("decode card invite: {e}"))?;

        assert_eq!(
            invite.stable_group_id.as_deref(),
            Some(stable_group_id.as_str())
        );
        assert_eq!(
            invite.base_state_hash.as_deref(),
            Some(authority_state_hash.as_str())
        );
        // #469 A1/E3: the card link is a SIGNED v4 invite whose roster
        // carrier is the projection — the legacy fat roster is never
        // set, and the projection re-derives the committed roster root.
        assert_eq!(
            invite.version,
            x0x::groups::invite::INVITE_VERSION_V4,
            "card link must be a v4 signed invite"
        );
        invite
            .verify_v4_signatures()
            .map_err(|r| anyhow::anyhow!("card invite must verify: {}", r.reason()))?;
        assert!(
            invite.base_members_v2.is_none(),
            "v4 invites never carry the legacy fat roster"
        );
        let projection = invite
            .base_roster
            .as_ref()
            .expect("v4 card invite carries the roster projection");
        assert_eq!(
            x0x::groups::state_commit::roster_root_of_projection(projection),
            x0x::groups::state_commit::compute_roster_root(&authority_members),
            "the projection re-derives the authority's committed roster root"
        );
        assert_eq!(
            invite.creator.as_deref(),
            Some(hex::encode(authority_id.as_bytes()).as_str()),
            "creator provenance survives card export (v4 explicit signed creator)"
        );
        // ORIGINAL INTENT ("card must not record secrets"): a card READ
        // used to mint-and-forget an untracked secret. #469 E3 makes the
        // read REUSE-OR-RECORD — the secret appears exactly once via the
        // mint transaction (origin Card, signed link recorded), and a
        // second read REUSES it instead of minting again.
        {
            let groups = authority.named_groups.read().await;
            let info = groups.get(&group_id).expect("authority group retained");
            let records: Vec<_> = info.issued_invites.values().collect();
            assert_eq!(
                records.len(),
                1,
                "the card read records exactly one CARD-origin invite"
            );
            let record = records[0];
            assert_eq!(record.origin, x0x::groups::InviteOrigin::Card);
            assert!(
                record.intended_joiner.is_none(),
                "card invites are unaddressed (reusable)"
            );
            assert_eq!(
                record.signed_link.as_deref(),
                Some(card_group.invite_link.as_str()),
                "the recorded signed link is what the card served"
            );
        }
        // Second read: REUSE — the identical link, still one record.
        let card_response2 = get_agent_card(
            State(Arc::clone(&authority)),
            Some(axum::extract::Extension(
                crate::server::rider_auth::ActorContext::Owner { durable: true },
            )),
            Query(CardQuery {
                display_name: Some("authority".to_string()),
                include_groups: Some(true),
                include_local_addresses: false,
            }),
        )
        .await
        .into_response();
        let (card_status2, card_body2) = response_json(card_response2).await?;
        assert_eq!(card_status2, StatusCode::OK);
        let card2: x0x::groups::card::AgentCard =
            serde_json::from_value(card_body2["card"].clone())
                .context("decode second agent card")?;
        let link2 = card2
            .groups
            .iter()
            .find(|group| group.name == "card invite provenance")
            .expect("second card includes the group")
            .invite_link
            .clone();
        assert_eq!(
            link2, card_group.invite_link,
            "second card read reuses the recorded signed link"
        );
        {
            let groups = authority.named_groups.read().await;
            let info = groups.get(&group_id).expect("authority group retained");
            assert_eq!(
                info.issued_invites.len(),
                1,
                "reuse must not mint a second secret"
            );
        }

        NAMED_GROUP_METADATA_PUBLISH_ATTEMPTS_FOR_TEST
            .lock()
            .expect("publish-attempt recorder poisoned")
            .clear();
        let join_response = join_group_via_invite(
            State(Arc::clone(&joiner)),
            Json(JoinGroupRequest {
                invite: card_group.invite_link.clone(),
                display_name: Some("joiner".to_string()),
                mode: None,
                expected_owner_user_id: None,
            }),
        )
        .await
        .into_response();
        let (join_status, join_body) = response_json(join_response).await?;

        assert_eq!(
            join_status,
            StatusCode::OK,
            "card invite join should be accepted, body: {join_body}"
        );
        assert_ne!(
            join_status,
            StatusCode::BAD_REQUEST,
            "card invite join must not fail with the pre-fix missing-base-state 400"
        );
        let joiner_hex = hex::encode(joiner.agent.agent_id().as_bytes());
        let metadata_topic = {
            let groups = joiner.named_groups.read().await;
            let stub = groups
                .get(&group_id)
                .expect("accepted card invite should create a local join stub");
            assert_eq!(stub.stable_group_id(), stable_group_id.as_str());
            assert_eq!(stub.state_hash, authority_state_hash);
            // #469 A1: the stub materializes from the invite's roster
            // PROJECTION (digest-only, no cert/key bytes) — identity of
            // the committed roster is pinned by its root, not map
            // equality with the authority's byte-bearing roster.
            assert_eq!(
                x0x::groups::state_commit::compute_roster_root(&stub.members_v2),
                x0x::groups::state_commit::compute_roster_root(&authority_members),
                "the projection-seeded stub re-derives the committed roster root"
            );
            assert!(
                !stub.has_active_member(&joiner_hex),
                "card-derived convergence remains Phase 2; this guard only proves accepted join stub formation"
            );
            stub.metadata_topic.clone()
        };
        let publish_attempts = NAMED_GROUP_METADATA_PUBLISH_ATTEMPTS_FOR_TEST
            .lock()
            .expect("publish-attempt recorder poisoned");
        assert!(
            publish_attempts
                .iter()
                .any(
                    |(topic, event_group_id, _recipient)| topic == &metadata_topic
                        && event_group_id == &stable_group_id
                ),
            "join handler should attempt to publish the joiner-authored MemberJoined request"
        );
        Ok(())
    }

    #[tokio::test]
    async fn agent_card_does_not_export_withdrawn_group_invites() -> Result<()> {
        let (state, _dir) = secure_endpoint_test_state().await?;
        let active_group_id = "6a".repeat(32);
        let withdrawn_group_id = "6b".repeat(32);
        let stale_active_group_id = "6c".repeat(32);
        let withdrawn_alias_group_id = "6d".repeat(32);
        let agent_id = state.agent.agent_id();
        let mut active = x0x::groups::GroupInfo::with_policy(
            "active card group".to_string(),
            String::new(),
            agent_id,
            active_group_id.clone(),
            x0x::groups::GroupPolicyPreset::PublicOpen.to_policy(),
        );
        active.recompute_state_hash();
        let mut withdrawn = x0x::groups::GroupInfo::with_policy(
            "withdrawn card group".to_string(),
            String::new(),
            agent_id,
            withdrawn_group_id.clone(),
            x0x::groups::GroupPolicyPreset::PublicOpen.to_policy(),
        );
        withdrawn.withdrawn = true;
        clear_group_info_key_material(&mut withdrawn);
        withdrawn.recompute_state_hash();
        let mut stale_active = x0x::groups::GroupInfo::with_policy(
            "stale active alias".to_string(),
            String::new(),
            agent_id,
            stale_active_group_id.clone(),
            x0x::groups::GroupPolicyPreset::PublicOpen.to_policy(),
        );
        stale_active.recompute_state_hash();
        let mut withdrawn_same_stable_alias = stale_active.clone();
        withdrawn_same_stable_alias.name = "withdrawn same-stable alias".to_string();
        withdrawn_same_stable_alias.mls_group_id = withdrawn_alias_group_id.clone();
        withdrawn_same_stable_alias.withdrawn = true;
        clear_group_info_key_material(&mut withdrawn_same_stable_alias);
        withdrawn_same_stable_alias.recompute_state_hash();
        {
            let mut groups = state.named_groups.write().await;
            groups.insert(active_group_id, active);
            groups.insert(withdrawn_group_id, withdrawn);
            groups.insert(stale_active_group_id, stale_active);
            groups.insert(withdrawn_alias_group_id, withdrawn_same_stable_alias);
        }

        let card_response = get_agent_card(
            State(Arc::clone(&state)),
            Some(axum::extract::Extension(
                crate::server::rider_auth::ActorContext::Owner { durable: true },
            )),
            Query(CardQuery {
                display_name: Some("authority".to_string()),
                include_groups: Some(true),
                include_local_addresses: false,
            }),
        )
        .await
        .into_response();
        let (status, body) = response_json(card_response).await?;
        assert_eq!(status, StatusCode::OK);
        let card: x0x::groups::card::AgentCard = serde_json::from_value(body["card"].clone())
            .context("decode agent card from handler response")?;

        assert!(
            card.groups
                .iter()
                .any(|group| group.name == "active card group"),
            "active groups should still be exported when include_groups=true"
        );
        assert!(
            card.groups
                .iter()
                .all(|group| group.name != "withdrawn card group"),
            "withdrawn tombstones must not be re-advertised as joinable card invites"
        );
        assert!(
            card.groups
                .iter()
                .all(|group| group.name != "stale active alias"),
            "stale active aliases for a withdrawn stable group must not be re-advertised"
        );
        Ok(())
    }

    // ── Card import trust-floor tests ───────────────────────────────────
    //
    // Regression: importing an agent card must never LOWER an existing
    // contact's trust level. A routine re-import (default trust_level:
    // "known") silently downgraded manually-trusted peers, breaking the
    // streams identity gate that requires unflagged `Accept` (Trusted →
    // Accept, Known → AcceptWithFlag).

    fn make_unsigned_card_link(display_name: &str, agent_id: &crate::identity::AgentId) -> String {
        let machine_id = hex::encode([0x11u8; 32]);
        let card =
            x0x::groups::card::AgentCard::new(display_name.to_string(), agent_id, &machine_id);
        card.to_link()
    }

    #[tokio::test]
    async fn card_import_does_not_downgrade_trusted_contact() -> Result<()> {
        let (state, _dir) = secure_endpoint_test_state().await?;
        let target_kp = crate::identity::AgentKeypair::generate()?;
        let target_id = target_kp.agent_id();

        // Pre-seed: manually trust the contact.
        state
            .contacts
            .write()
            .await
            .set_trust(&target_id, x0x::contacts::TrustLevel::Trusted);

        // Import card with trust_level "known" — must NOT downgrade.
        let card_link = make_unsigned_card_link("Alice", &target_id);
        let req: ImportCardRequest = serde_json::from_value(serde_json::json!({
            "card": card_link,
            "trust_level": "known"
        }))
        .context("deserialize ImportCardRequest")?;
        let response = import_agent_card(State(Arc::clone(&state)), Json(req))
            .await
            .into_response();
        let (status, body) = response_json(response).await?;
        assert_eq!(status, StatusCode::OK);

        // Response must show effective trust = Trusted and flag the ignored downgrade.
        assert_eq!(
            body["trust_level"], "Trusted",
            "import must not downgrade a trusted contact"
        );
        assert_eq!(
            body["trust_change_ignored"], true,
            "response must flag that the requested downgrade was ignored"
        );

        // Store must still show Trusted.
        let stored = state.contacts.read().await.trust_level(&target_id);
        assert_eq!(
            stored,
            x0x::contacts::TrustLevel::Trusted,
            "contact store must retain Trusted after card import"
        );
        Ok(())
    }

