    /// Why (PR #370 review item 2): a retained withdrawn tombstone is an
    /// anti-resurrection record, not a live group — GET /groups must omit it
    /// while GET /groups/:id still serves it with `withdrawn: true`.
    #[tokio::test]
    async fn withdrawn_tombstone_hidden_from_groups_listing() -> Result<()> {
        let (state, _dir) = secure_endpoint_test_state().await?;
        let live_id = "listing-live".to_string();
        let tombstone_id = "listing-tombstone".to_string();
        let mut live = x0x::groups::GroupInfo::with_policy(
            "live".to_string(),
            String::new(),
            state.agent.agent_id(),
            live_id.clone(),
            x0x::groups::GroupPolicyPreset::PublicOpen.to_policy(),
        );
        live.secure_plane = x0x::mls::SecureGroupPlane::Gss;
        live.recompute_state_hash();
        let mut tombstone = live.clone();
        tombstone.name = "gone".to_string();
        tombstone.withdrawn = true;
        let mut groups = state.named_groups.write().await;
        groups.insert(live_id.clone(), live);
        groups.insert(tombstone_id.clone(), tombstone);
        drop(groups);

        let (list_status, list_body) = response_json(
            list_named_groups(State(Arc::clone(&state)))
                .await
                .into_response(),
        )
        .await?;
        assert_eq!(list_status, StatusCode::OK);
        let listed: Vec<&str> = list_body["groups"]
            .as_array()
            .expect("groups array")
            .iter()
            .filter_map(|g| g["name"].as_str())
            .collect();
        assert!(listed.contains(&"live"), "live group listed: {listed:?}");
        assert!(
            !listed.contains(&"gone"),
            "withdrawn tombstone must not appear in GET /groups: {listed:?}"
        );

        let (get_status, get_body) = response_json(
            get_named_group(State(Arc::clone(&state)), Path(tombstone_id.clone()))
                .await
                .into_response(),
        )
        .await?;
        assert_eq!(get_status, StatusCode::OK);
        assert_eq!(
            get_body["withdrawn"], true,
            "tombstone detail must carry withdrawn:true: {get_body:?}"
        );
        Ok(())
    }

    // ── Non-TreeKEM JoinRequestApproved fan-out: the approval handler must
    // deliver the signed JoinRequestApproved to EVERY non-local active member
    // (the already-present witnesses) AND the new requester, on BOTH the direct
    // and delayed paths — the same property the TreeKEM approval sibling
    // (:11461) and the remove handler (:8730) already satisfy. Before the fix,
    // `approve_join_request` delivered only to the requester, so a witness off
    // the eager mesh never learned a peer had been approved and stayed at the
    // old roster revision. This is the source-pinned root cause of MiniMax's
    // daemon-family R2 barrier failure: Alice approved Charlie, but Bob (an
    // already-active witness) never received Charlie's JoinRequestApproved and
    // so never saw Charlie in his /members — not a window-too-short problem.
    //
    // The recorder now carries the full event kind, so this test filters on
    // "join_request_approved" and cannot infer the event from recipient
    // presence alone (a MemberRemoved or SecureShareDelivered to the same
    // recipient would not satisfy it).
    //
    // Sensitivity arms (mutated separately, then restored — REQUIRED red):
    //   Arm 1 (requester-only regression): restore the old requester-only
    //     delivery `spawn_named_group_event_delivery(&state, &requester_hex,
    //     &event)` (direct, no active-member fan-out) → the WITNESS
    //     assertions fail on both paths; requester-direct stays green (it was
    //     already delivered) and requester-delayed also fails because the old
    //     path had no delayed retry. The witness is the catcher for the new
    //     active-member-delivery property.
    //   Arm 2 (drop delayed path): inside
    //     spawn_named_group_event_delivery_to_active_members, comment out the
    //     spawn_named_group_event_delivery_after call → the delayed set loses
    //     every recipient while the direct set is unchanged; the delayed
    //     assertions fail, immediate delivery remains.
    #[tokio::test]
    async fn non_treekem_approve_directly_delivers_join_request_approved_to_witness_and_requester(
    ) -> Result<()> {
        let (state, _dir) = secure_endpoint_test_state().await?;
        let admin_id = state.agent.agent_id();
        let local_hex = hex::encode(state.agent.agent_id().as_bytes());

        // One already-active witness and one pending requester (not yet a
        // member — the handler adds them on approval).
        let witness_hex = hex::encode(
            crate::identity::AgentKeypair::generate()?
                .agent_id()
                .as_bytes(),
        );
        let witness_kem_b64 =
            BASE64.encode(&x0x::groups::kem_envelope::AgentKemKeypair::generate()?.public_bytes);
        let requester_kp = crate::identity::AgentKeypair::generate()?;
        let requester_hex = hex::encode(requester_kp.agent_id().as_bytes());

        let group_id = "approve-delivery-local".to_string();
        let stable_group_id = "approve-delivery-stable".to_string();

        let mut info = x0x::groups::GroupInfo::with_policy(
            "join-approval direct delivery".to_string(),
            String::new(),
            admin_id,
            group_id.clone(),
            x0x::groups::GroupPolicyPreset::PrivateSecure.to_policy(),
        );
        info.genesis = Some(x0x::groups::state_commit::GroupGenesis::with_existing_id(
            stable_group_id.clone(),
            local_hex.clone(),
            info.created_at,
            String::new(),
        ));
        info.secure_plane = x0x::mls::SecureGroupPlane::Gss;
        // The witness is already an active member; the requester is pending.
        info.add_member_with_kem(
            witness_hex.clone(),
            x0x::groups::GroupRole::Member,
            Some(local_hex.clone()),
            None,
            Some(witness_kem_b64),
        );
        let request = x0x::groups::JoinRequest::new(
            group_id.clone(),
            requester_hex.clone(),
            None,
            now_millis_u64(),
        );
        let request_id = request.request_id.clone();
        info.join_requests.insert(request_id.clone(), request);
        info.recompute_state_hash();
        state
            .named_groups
            .write()
            .await
            .insert(group_id.clone(), info);

        adr0028_direct_controls::offer_predecessor_obligation_via_real_path(
            &state,
            &group_id,
            &request_id,
            &requester_kp,
        )
        .await;

        // Positive precondition: GSS plane, so the TreeKem dispatch at the top
        // of approve_join_request cannot fire and the non-TreeKEM path (the one
        // under test) is exercised.
        {
            let groups = state.named_groups.read().await;
            let stored = groups.get(&group_id).expect("group present");
            assert_eq!(
                stored.secure_plane,
                x0x::mls::SecureGroupPlane::Gss,
                "must exercise the non-TreeKEM (GSS) approve path, not the TreeKem dispatch"
            );
        }

        NAMED_GROUP_DIRECT_DELIVERIES_FOR_TEST
            .lock()
            .expect("delivery recorder poisoned")
            .clear();

        let (status, body) = response_json(
            approve_join_request(
                State(Arc::clone(&state)),
                axum::extract::Extension(crate::server::rider_auth::ActorContext::Owner {
                    durable: true,
                }),
                Path((group_id.clone(), request_id.clone())),
            )
            .await
            .into_response(),
        )
        .await?;

        assert_eq!(
            status,
            StatusCode::OK,
            "admin approval of a pending request must succeed, body: {body}"
        );

        // The JoinRequestApproved delivery set, split by path. Filter on the
        // event kind so a SecureShareDelivered or MemberRemoved to the same
        // recipient cannot satisfy the assertion. Collect each path
        // independently and assert the witness AND requester appear in BOTH —
        // loss of either path or either recipient is caught.
        let recipients_for = |kind: &str| -> Vec<String> {
            NAMED_GROUP_DIRECT_DELIVERIES_FOR_TEST
                .lock()
                .expect("delivery recorder poisoned")
                .iter()
                .filter(|(_, gid, ev_kind, k)| {
                    gid == &stable_group_id && *ev_kind == "join_request_approved" && *k == kind
                })
                .map(|(recipient, _, _, _)| recipient.clone())
                .collect()
        };
        let direct = recipients_for("direct");
        let delayed = recipients_for("delayed");

        assert!(
            !direct.is_empty() && !delayed.is_empty(),
            "the approve handler must deliver the JoinRequestApproved via BOTH paths; \
             direct={direct:?} delayed={delayed:?}"
        );
        assert!(
            direct.contains(&witness_hex) && delayed.contains(&witness_hex),
            "an already-active WITNESS must receive the JoinRequestApproved on BOTH the direct \
             and delayed paths (the daemon-family R2 gap: without active-member fan-out, a \
             witness off the eager mesh never learns a peer was approved and stays at the old \
             roster revision); direct={direct:?} delayed={delayed:?}"
        );
        assert!(
            direct.contains(&requester_hex) && delayed.contains(&requester_hex),
            "the new REQUESTER must receive the JoinRequestApproved on BOTH the direct and \
             delayed paths; direct={direct:?} delayed={delayed:?}"
        );
        Ok(())
    }
    // ── Gate item 2 (survivor decryptability): a survivor — a member still
    // Active after an admin remove of a peer — CAN decrypt content the system
    // PUBLISHED at the new epoch. The plaintext is published through the
    // production `secure_group_encrypt` endpoint and read back through the
    // production `secure_group_decrypt` endpoint — a true GSS-plane round-trip
    // (Watson [12] §3 / Dario [13] §2), not an in-test envelope, so encrypt-
    // side drift (AAD, key sourcing) cannot stay green here. The positive
    // complement to item 4: item 4 proves the removed member cannot decrypt;
    // item 2 proves the survivors still can.
    //
    // Interval (ADR 0024 break-disclosure rule): `secure_group_decrypt` entry
    // (`:12297`) → target operation `cipher.decrypt` (`:12381`). Resolves at
    // `9d11d69`; receipt (ADR 0024 `9fb3b20`): `head -n 16378` of this file
    // ⇒ sha256 `89bb14e96b3f71525d5cd3d746eb1a71573b94d462b32986ba64a2d2d5d33ccb`,
    // identical at `9d11d69` and `6cc03e5`. Highest cite `:12408` < 16378,
    // and this commit edits no line ≤ 16378, so the hash holds here too.
    // Re-resolve after any rebase.
    //
    // Break list — every control-flow exit / alternate dispatch in the
    // interval, each with its evidence:
    //   :12305 group-not-found     — refused (installed group)
    //   :12308 withdrawn           — refused (non-withdrawn group)
    //   :12312 not-a-member        — MUTATION B + positive membership assert
    //   :12320 TreeKem dispatch    — refused (assert secure_plane == Gss)
    //   :12328 no shared secret    — refused (secret installed)
    //   :12339 epoch mismatch      — refused (matching epoch sent)
    //   :12354 bad base64 ct       — refused (valid base64)
    //   :12360 bad base64 nonce    — refused (valid base64)
    //   :12364 nonce wrong length  — refused (12-byte nonce)
    //   :12376 cipher init failed  — refused (derive_message_key returns 32B)
    //   :12408 cipher Err          — MUTATION A (stored-secret byte flip)
    //   :12396 post-decrypt terminality recheck (→ :10141, hook :10148) —
    //     FALSE-NEGATIVE hazard: can suppress a success into a 409 conflict,
    //     cannot manufacture plaintext. Refused by the success-shape
    //     precondition (status 200 + payload present + no conflict). NOT a
    //     blind spot. `force_post_crypto_withdrawn_ids` is NOT installed.
    //
    // Mutation A: between the production encrypt and decrypt calls, flip one
    // byte in the stored `shared_secret`. The ciphertext was sealed under the
    // original; decrypt derives from the flipped secret → wrong key → `:12408`
    // "decryption failed" → the success assertion fails. Shows the gate
    // observes the cipher path (`:12408`), distinct from the `:12312` roster
    // guard exercised by mutation B.
    //
    // Mutation B: `remove_member(&survivor)` after setup → survivor Removed →
    // the `:12312` roster guard fires → "not a member" → success assertion
    // fails. Shows the gate observes active membership at `:12312`.
    //
    // Mutation SYM/ASYM (round-trip teeth — Watson [12] §2 / Dario [13] §1):
    //   ASYM — change the AAD on the ENCRYPT side only (`:12251`) → this gate
    //     RED, sole failure (encrypt and decrypt no longer agree). REQUIRED
    //     red arm of the mutation set (`8053a3d`).
    //   SYM  — change the AAD on BOTH production sides (`:12251` + `:12380`)
    //     → all green. ACCEPTED BLIND SPOT (direction test, `8053a3d`):
    //     symmetric drift is invisible because the gate observes the two
    //     endpoints agreeing with each other, not with any prior format — a
    //     compatibility property, not a decryptability one. Nothing in the F1
    //     set observes it; named, not fixed.
    //
    // Epoch-binding pin: `derive_message_key` mixes the epoch into the key
    // (`groups/mod.rs:744`); Watson's M4 showed nothing in the F1 set observes
    // it. A direct pure-fn pair asserts different epochs yield different keys,
    // complementing 4b (which pins the secret binding).
    #[tokio::test]
    async fn f1_item2_survivor_decrypts_new_epoch_content() -> Result<()> {
        let (state, _dir) = secure_endpoint_test_state().await?;
        let local_hex = hex::encode(state.agent.agent_id().as_bytes());
        // Admin/creator is a distinct agent; the local daemon is the survivor.
        let admin_id = crate::identity::AgentKeypair::generate()?.agent_id();
        let admin_hex = hex::encode(admin_id.as_bytes());

        let group_id = "f1-item2-local".to_string();
        let stable_group_id = "f1-item2-stable".to_string();
        let epoch: u64 = 7;
        let secret: Vec<u8> = vec![0x42; 32];

        let mut info = x0x::groups::GroupInfo::with_policy(
            "f1 item2 survivor decrypt".to_string(),
            String::new(),
            admin_id,
            group_id.clone(),
            x0x::groups::GroupPolicyPreset::PrivateSecure.to_policy(),
        );
        info.genesis = Some(x0x::groups::state_commit::GroupGenesis::with_existing_id(
            stable_group_id.clone(),
            admin_hex.clone(),
            info.created_at,
            String::new(),
        ));
        info.secure_plane = x0x::mls::SecureGroupPlane::Gss;
        info.secret_epoch = epoch;
        info.shared_secret = Some(secret.clone());
        info.add_member(
            local_hex.clone(),
            x0x::groups::GroupRole::Member,
            Some(admin_hex.clone()),
            None,
        );
        info.recompute_state_hash();
        state
            .named_groups
            .write()
            .await
            .insert(group_id.clone(), info);

        // Positive preconditions: GSS plane (explicit, not inherited) and the
        // survivor really is an Active member.
        {
            let groups = state.named_groups.read().await;
            let stored = groups.get(&group_id).expect("item2 group present");
            assert_eq!(
                stored.secure_plane,
                x0x::mls::SecureGroupPlane::Gss,
                "item2 must exercise the GSS decrypt path, not the TreeKem dispatch"
            );
            assert!(
                stored.has_active_member(&local_hex),
                "survivor (local daemon) must be Active before decrypt"
            );
        }

        // PUBLISH the plaintext through the production `secure_group_encrypt`
        // endpoint — content the system actually produced, not minted in-test.
        // For this group the GSS plane is active, so encrypt derives the key
        // from `info.secure_message_key()` (the stored secret at `epoch`),
        // generates a fresh per-message nonce, and seals with the production
        // AAD. The returned `ciphertext_b64` / `nonce_b64` are what a survivor
        // would actually receive.
        let plaintext = b"item2 survivor new-epoch plaintext";
        let (enc_status, enc_body) = secure_group_encrypt(
            State(Arc::clone(&state)),
            Path(group_id.clone()),
            axum::Extension(crate::server::rider_auth::ActorContext::Owner { durable: true }),
            Json(SecureEncryptRequest {
                payload_b64: BASE64.encode(plaintext),
            }),
        )
        .await;
        assert_eq!(
            enc_status,
            StatusCode::OK,
            "production encrypt must succeed for an active survivor; body: {enc_body:?}"
        );
        assert_eq!(
            enc_body.0["ok"].as_bool(),
            Some(true),
            "encrypt must report ok, body: {enc_body:?}"
        );
        let ciphertext_b64 = enc_body.0["ciphertext_b64"]
            .as_str()
            .expect("encrypt response carries ciphertext_b64")
            .to_string();
        let nonce_b64 = enc_body.0["nonce_b64"]
            .as_str()
            .expect("encrypt response carries nonce_b64")
            .to_string();
        assert_eq!(
            enc_body.0["secret_epoch"].as_u64(),
            Some(epoch),
            "encrypt must bind the group's current secret_epoch"
        );

        // Production endpoint decrypt, as the survivor, of the published
        // ciphertext (the exact bytes the system just produced above).
        let (status, body) = secure_group_decrypt(
            State(Arc::clone(&state)),
            Path(group_id.clone()),
            Json(SecureDecryptRequest {
                ciphertext_b64,
                nonce_b64,
                secret_epoch: epoch,
            }),
        )
        .await;

        // Success-shape precondition (refuses the eleventh false-negative
        // path): status 200 + payload present + ok, NOT a 409 conflict.
        assert_eq!(
            status,
            StatusCode::OK,
            "survivor must decrypt new-epoch content"
        );
        assert_eq!(
            body.0["ok"].as_bool(),
            Some(true),
            "decrypt must report ok, body: {body:?}"
        );
        let payload_b64 = body.0["payload_b64"]
            .as_str()
            .expect("success response carries payload_b64");
        assert_eq!(
            BASE64.decode(payload_b64).expect("payload is base64"),
            plaintext,
            "decrypted plaintext must match"
        );
        assert_eq!(
            body.0["secret_epoch"].as_u64(),
            Some(epoch),
            "echoed epoch must match the ciphertext epoch"
        );

        // Epoch-binding pin in the derivation (`groups/mod.rs:744`). Nothing
        // else in the F1 set observes this; 4b pins the secret binding.
        let key_this = x0x::groups::GroupInfo::derive_message_key(&secret, epoch, &stable_group_id);
        let key_next =
            x0x::groups::GroupInfo::derive_message_key(&secret, epoch + 1, &stable_group_id);
        assert_ne!(
            key_this, key_next,
            "derive_message_key must bind the epoch; identical keys across epochs would let a \
             stale-epoch holder derive the new-epoch key"
        );

        Ok(())
    }

    fn treekem_metadata_group_info(
        creator: AgentId,
        group_id: &str,
        stable_group_id: &str,
    ) -> x0x::groups::GroupInfo {
        let creator_hex = hex::encode(creator.as_bytes());
        let mut info = x0x::groups::GroupInfo::with_policy(
            "secure".to_string(),
            String::new(),
            creator,
            group_id.to_string(),
            x0x::groups::GroupPolicyPreset::PrivateSecure.to_policy(),
        );
        info.genesis = Some(x0x::groups::state_commit::GroupGenesis::with_existing_id(
            stable_group_id.to_string(),
            creator_hex,
            info.created_at,
            String::new(),
        ));
        info.secure_plane = x0x::mls::SecureGroupPlane::TreeKem;
        info.shared_secret = None;
        info.secret_epoch = 0;
        info.security_binding = Some("treekem:epoch=0".to_string());
        info.recompute_state_hash();
        info
    }

    pub(in crate::server) struct MemberJoinedTreeKemFixture {
        pub(in crate::server) state: Arc<AppState>,
        pub(in crate::server) _dir: tempfile::TempDir,
        pub(in crate::server) group_id: String,
        stable_group_id: String,
        member_id: AgentId,
        member_hex: String,
        event: NamedGroupMetadataEvent,
        group: Arc<Mutex<x0x::mls::TreeKemMlsGroup>>,
        initial_epoch: u64,
    }

    pub(in crate::server) async fn member_joined_treekem_fixture(
        group_byte: u8,
        stable_byte: u8,
    ) -> Result<MemberJoinedTreeKemFixture> {
        let (state, dir) = secure_endpoint_test_state().await?;
        let group_id = format!("{group_byte:02x}").repeat(32);
        let stable_group_id = format!("{stable_byte:02x}").repeat(32);
        let group_id_bytes = hex::decode(&group_id)?;
        let inviter = state.agent.agent_id();
        let inviter_hex = hex::encode(inviter.as_bytes());
        let creator_seed = agent_treekem_seed(state.agent.as_ref(), &group_id_bytes);
        let live_group = x0x::mls::TreeKemMlsGroup::create(group_id_bytes, inviter, &creator_seed)?;
        let initial_epoch = live_group.epoch();
        let group = Arc::new(Mutex::new(live_group));
        state
            .treekem_groups
            .write()
            .await
            .insert(group_id.clone(), Arc::clone(&group));

        let mut info = treekem_metadata_group_info(inviter, &group_id, &stable_group_id);
        let now_ms = now_millis_u64();
        let invite_secret = format!("member-joined-invite-{group_byte:02x}");
        info.record_issued_invite(
            invite_secret.clone(),
            now_ms / 1_000,
            0,
            x0x::groups::GroupRole::Member,
        );
        state
            .named_groups
            .write()
            .await
            .insert(group_id.clone(), info);

        let member_keypair = x0x::identity::AgentKeypair::generate()?;
        let member_id = member_keypair.agent_id();
        let member_hex = hex::encode(member_id.as_bytes());
        let member_public_key_b64 = BASE64.encode(member_keypair.public_key().as_bytes());
        let member_seed = [stable_byte; 32];
        let prepared = x0x::mls::TreeKemMlsGroup::prepare_member(member_id, &member_seed)?;
        let treekem_key_package_b64 = BASE64.encode(prepared.key_package_bytes());
        let canonical = canonical_member_joined_bytes(
            &group_id,
            Some(&stable_group_id),
            &member_hex,
            &member_public_key_b64,
            x0x::groups::GroupRole::Member,
            None,
            &inviter_hex,
            &invite_secret,
            now_ms,
            Some(&treekem_key_package_b64),
        );
        let signature = ant_quic::crypto::raw_public_keys::pqc::sign_with_ml_dsa(
            member_keypair.secret_key(),
            &canonical,
        )
        .map_err(|e| anyhow::anyhow!("sign MemberJoined fixture: {e:?}"))?;
        let event = NamedGroupMetadataEvent::MemberJoined {
            group_id: group_id.clone(),
            stable_group_id: Some(stable_group_id.clone()),
            member_agent_id: member_hex.clone(),
            member_public_key_b64,
            role: x0x::groups::GroupRole::Member,
            display_name: None,
            inviter_agent_id: inviter_hex,
            invite_secret,
            ts_ms: now_ms,
            treekem_key_package_b64: Some(treekem_key_package_b64),
            recovery_authority_agent_id: None,
            recovery_authority_public_key_b64: None,
            recovery_authority_signature_b64: None,
            recovery_authority_commit: None,
            signature_b64: BASE64.encode(signature.as_bytes()),
        };
        let (recovery_commit, retained_commit) = {
            let groups = state.named_groups.read().await;
            let mut accepted = groups.get(&group_id).expect("fixture group exists").clone();
            accepted.roster_revision = accepted.roster_revision.saturating_add(1);
            accepted.add_member(
                member_hex.clone(),
                x0x::groups::GroupRole::Member,
                Some(hex::encode(state.agent.agent_id().as_bytes())),
                None,
            );
            if let NamedGroupMetadataEvent::MemberJoined {
                treekem_key_package_b64: Some(kp_b64),
                ..
            } = &event
            {
                accepted.set_member_treekem_key_package(&member_hex, kp_b64.clone());
            }
            accepted.secret_epoch = initial_epoch.saturating_add(1);
            accepted.security_binding =
                treekem_recovery_security_binding(accepted.secret_epoch, &event);
            let commit = seal_commit_owner_certified(
                &state,
                &mut accepted,
                state.agent.identity().agent_keypair(),
                now_ms,
            )
            .await?;
            let retained = accepted
                .commit_log
                .last()
                .cloned()
                .expect("sealed fixture commit retained");
            (commit, retained)
        };
        state
            .named_groups
            .write()
            .await
            .get_mut(&group_id)
            .expect("fixture group exists")
            .commit_log
            .push(retained_commit);
        {
            let mut groups = state.named_groups.write().await;
            let info = groups.get_mut(&group_id).expect("fixture group exists");
            info.add_member(
                member_hex.clone(),
                x0x::groups::GroupRole::Member,
                Some(hex::encode(state.agent.agent_id().as_bytes())),
                None,
            );
            if let NamedGroupMetadataEvent::MemberJoined {
                treekem_key_package_b64: Some(kp_b64),
                ..
            } = &event
            {
                info.set_member_treekem_key_package(&member_hex, kp_b64.clone());
                info.members_v2
                    .get_mut(&member_hex)
                    .expect("fixture member exists")
                    .treekem_key_package_b64 = None;
            }
            info.remove_member(&member_hex, None);
            info.recompute_state_hash();
        }
        let event = attest_member_joined_recovery_event(
            &event,
            state.agent.identity().agent_keypair(),
            &recovery_commit,
        )?;

        Ok(MemberJoinedTreeKemFixture {
            state,
            _dir: dir,
            group_id,
            stable_group_id,
            member_id,
            member_hex,
            event,
            group,
            initial_epoch,
        })
    }

    async fn add_active_witness_to_treekem_fixture(
        fixture: &MemberJoinedTreeKemFixture,
        witness: &Arc<AppState>,
    ) -> Result<()> {
        let group_id_bytes = hex::decode(&fixture.group_id)?;
        let witness_id = witness.agent.agent_id();
        let witness_hex = hex::encode(witness_id.as_bytes());
        let witness_seed = agent_treekem_seed(witness.agent.as_ref(), &group_id_bytes);
        let prepared = x0x::mls::TreeKemMlsGroup::prepare_member(witness_id, &witness_seed)?;
        let (welcome, epoch) = {
            let mut owner_group = fixture.group.lock().await;
            let add = owner_group.add_member(witness_id, prepared.key_package_bytes())?;
            (add.welcome, owner_group.epoch())
        };
        let witness_group = x0x::mls::TreeKemMlsGroup::join_from_welcome(prepared, &welcome)?;
        let info = {
            let mut groups = fixture.state.named_groups.write().await;
            let info = groups
                .get_mut(&fixture.group_id)
                .expect("owner fixture retains group");
            info.add_member(
                witness_hex,
                x0x::groups::GroupRole::Member,
                Some(hex::encode(fixture.state.agent.agent_id().as_bytes())),
                None,
            );
            info.secret_epoch = epoch;
            info.security_binding = Some(format!("treekem:epoch={epoch}"));
            info.recompute_state_hash();
            info.clone()
        };
        witness
            .named_groups
            .write()
            .await
            .insert(fixture.group_id.clone(), info);
        witness.treekem_groups.write().await.insert(
            fixture.group_id.clone(),
            Arc::new(Mutex::new(witness_group)),
        );
        Ok(())
    }

    fn signed_member_joined_event_for_test(
        keypair: &x0x::identity::AgentKeypair,
        group_id: &str,
        inviter_agent_id: &str,
        invite_secret: &str,
        role: x0x::groups::GroupRole,
    ) -> Result<(AgentId, String, String, NamedGroupMetadataEvent)> {
        let member_id = keypair.agent_id();
        let member_hex = hex::encode(member_id.as_bytes());
        let member_public_key_b64 = BASE64.encode(keypair.public_key().as_bytes());
        let ts_ms = now_millis_u64();
        let canonical = canonical_member_joined_bytes(
            group_id,
            Some(group_id),
            &member_hex,
            &member_public_key_b64,
            role,
            None,
            inviter_agent_id,
            invite_secret,
            ts_ms,
            None,
        );
        let signature = ant_quic::crypto::raw_public_keys::pqc::sign_with_ml_dsa(
            keypair.secret_key(),
            &canonical,
        )
        .map_err(|e| anyhow::anyhow!("sign MemberJoined fixture: {e:?}"))?;
        let event = NamedGroupMetadataEvent::MemberJoined {
            group_id: group_id.to_string(),
            stable_group_id: Some(group_id.to_string()),
            member_agent_id: member_hex.clone(),
            member_public_key_b64: member_public_key_b64.clone(),
            role,
            display_name: None,
            inviter_agent_id: inviter_agent_id.to_string(),
            invite_secret: invite_secret.to_string(),
            ts_ms,
            treekem_key_package_b64: None,
            recovery_authority_agent_id: None,
            recovery_authority_public_key_b64: None,
            recovery_authority_signature_b64: None,
            recovery_authority_commit: None,
            signature_b64: BASE64.encode(signature.as_bytes()),
        };
        Ok((member_id, member_hex, member_public_key_b64, event))
    }

    async fn group_counters_for_test(
        state: &Arc<AppState>,
        group_id: &str,
    ) -> x0x::groups::GroupCounters {
        let groups = state.named_groups.read().await;
        let empty_topics = HashSet::new();
        state
            .groups_diagnostics
            .snapshot(&groups, &empty_topics, &empty_topics, &HashMap::new())
            .groups
            .into_iter()
            .find(|row| row.group_id == group_id)
            .map(|row| row.counters)
            .unwrap_or_default()
    }

    #[tokio::test]
    async fn member_joined_forged_role_and_unknown_secret_rejected_single_app_state() -> Result<()>
    {
        let (state, _dir) = secure_endpoint_test_state().await?;
        let group_id = "61".repeat(32);
        let inviter = state.agent.agent_id();
        let inviter_hex = hex::encode(inviter.as_bytes());
        let now_ms = now_millis_u64();
        let invite_secret = "single-app-state-member-joined-invite".to_string();
        let mut info = x0x::groups::GroupInfo::with_policy(
            "single-app-state MemberJoined rejection".to_string(),
            String::new(),
            inviter,
            group_id.clone(),
            x0x::groups::GroupPolicyPreset::PublicOpen.to_policy(),
        );
        info.record_issued_invite(
            invite_secret.clone(),
            now_ms / 1_000,
            0,
            x0x::groups::GroupRole::Member,
        );
        state
            .named_groups
            .write()
            .await
            .insert(group_id.clone(), info);
        assert!(save_named_groups(&state).await);

        let forger = x0x::identity::AgentKeypair::generate()?;
        let (forger_id, forger_hex, forger_public_key_b64, forged_admin) =
            signed_member_joined_event_for_test(
                &forger,
                &group_id,
                &inviter_hex,
                &invite_secret,
                x0x::groups::GroupRole::Admin,
            )?;
        let should_exit = apply_named_group_metadata_event_inner(
            &state,
            forged_admin,
            forger_id,
            true,
            true,
            None,
        )
        .await;
        assert!(!should_exit.should_exit);
        let counters = group_counters_for_test(&state, &group_id).await;
        assert_eq!(
            counters.member_joined_events_rejected_non_member_role, 1,
            "forged admin MemberJoined must be counted as a role-policy rejection"
        );

        let (_, _, _, forged_unknown_secret) = signed_member_joined_event_for_test(
            &forger,
            &group_id,
            &inviter_hex,
            &"00".repeat(32),
            x0x::groups::GroupRole::Member,
        )?;
        let should_exit = apply_named_group_metadata_event_inner(
            &state,
            forged_unknown_secret,
            forger_id,
            true,
            true,
            None,
        )
        .await;
        assert!(!should_exit.should_exit);
        let counters = group_counters_for_test(&state, &group_id).await;
        assert_eq!(
            counters.member_joined_events_rejected_invite_secret_unknown, 1,
            "unknown invite-secret MemberJoined must be counted as an invite-policy rejection"
        );
        assert_eq!(
            counters.member_joined_events_applied, 0,
            "forged MemberJoined events must not apply"
        );

        let groups = state.named_groups.read().await;
        let live = groups.get(&group_id).expect("group retained");
        assert!(
            !live.has_active_member(&forger_hex),
            "forged MemberJoined must not admit the sender"
        );
        drop(groups);
        let persisted = tokio::fs::read_to_string(&state.named_groups_path).await?;
        assert!(
            !persisted.contains(&forger_hex),
            "forged member id must not be persisted after rejection"
        );
        assert!(
            !persisted.contains(&forger_public_key_b64),
            "forged member public key / protected material must not be persisted after rejection"
        );
        Ok(())
    }

    async fn assert_member_joined_treekem_did_not_install(
        fixture: &MemberJoinedTreeKemFixture,
    ) -> Result<()> {
        let guard = fixture.group.lock().await;
        assert_eq!(
            guard.epoch(),
            fixture.initial_epoch,
            "rejected MemberJoined must roll back in-memory TreeKEM epoch"
        );
        assert_eq!(
            guard.member_count(),
            1,
            "rejected MemberJoined must not leave an added TreeKEM leaf"
        );
        drop(guard);
        assert!(
            !tokio::fs::try_exists(treekem_snapshot_path(
                &fixture.state.treekem_dir,
                &fixture.group_id,
            ))
            .await?,
            "rejected MemberJoined must not persist TreeKEM snapshot material"
        );
        let groups = fixture.state.named_groups.read().await;
        let live = groups
            .get(&fixture.group_id)
            .expect("live group record retained");
        assert!(
            !live.has_active_member(&fixture.member_hex),
            "rejected MemberJoined must not store roster/key-state advance"
        );
        Ok(())
    }

