        let add =
            authority_group.add_member(state.agent.agent_id(), prepared.key_package_bytes())?;
        let joined = x0x::mls::TreeKemMlsGroup::join_from_welcome(prepared, &add.welcome)?;
        let epoch = joined.epoch();
